(()=>{
  const params=new URLSearchParams(location.search),days=['Monday','Tuesday','Wednesday','Thursday','Friday'];
  const raw=params.get('day'),day=days.includes(raw)?days.indexOf(raw):Math.max(0,Math.min(4,new Date().getDay()-1));
  const embedded=params.get('from')==='runner'&&window.parent!==window,destination=embedded?window.parent:window;
  const overview=()=>{localStorage.removeItem('eea-lesson-auto-resume');destination.location.href='daily-lessons.html?week=10&day='+day;};
  if(!days.includes(raw)){overview();return;}
  const mondayPlan=[{"title": "Nature Arrangements", "center": "Art Studio", "lead": "This week, we will make one big arrangement together. We can all take turns adding to and changing the arrangement.", "img": "assets/focus-3s/unit-2/week-1/centers/nature-arrangements.png", "alt": "Illustration of children arranging autumn leaves, pinecones, acorns and other natural materials together on a large tray.", "source": "https://drive.google.com/file/d/1O0tu19Bq53aaPOBqYFkG9KynYpNwMsr8/view", "notes": [["Continued from Week 1", ["Use teacher-held photographs of the children’s actual arrangements for the introduction. The on-screen illustration is an existing companion illustration, not a photograph of this class’s work. No child-work photographs are uploaded or stored here."]], ["Vocabulary", ["arrange: to place things in a thoughtful way", "autumn: another word for Fall; the season after summer where the temperature is cooler and the leaves on trees turn yellow, orange and red", "rough: bumpy, not smooth", "smooth: even and flat to the touch", "texture: how something feels"]], ["Additional Materials", ["photographs of children’s nature arrangements from previous week, printed or ready to project", "additional natural materials to add to the collection, such as new leaves, pinecones, sticks, etc.", "optional: large tray, tupperware container lid, or piece of cardboard to use as a base for the group arrangement (or just create the arrangement directly on the Art Table, if you can leave it out for multiple days)"]], ["Preparation", ["Replenish natural materials as needed, encouraging children to gather and share items they may find near their homes, at a park, or on the play yard.", "This week, children will be adding to and revisiting a shared arrangement over several days. Set up this experience in a place where the materials can be left out uninterrupted all week."]], ["Intro to Centers", ["So many people made nature arrangements in the Art Studio last week! Let’s look at some of your arrangements.", "Project or show photographs of the children’s work from the previous week. Use compare/contrast language to notice some similarities and differences in the materials children used.", "Lin used more big leaves than small leaves… Jamir used fewer acorns than Saanj. What do you notice?", "Invite children to respond.", "Today we have some new materials to add to our leaf arrangements.", "Show and name new materials.", "This week, we will make one big arrangement together. We can use the whole Art Studio table as our background, and we can all take turns adding to and changing the arrangement.", "We will be making a book of our nature arrangements to keep in our classroom library. If you haven’t tried making an arrangement yet, visit the Art Studio to give it a try."]], ["Extension", ["Instead of making individual arrangements, encourage collaboration by identifying a space where a collective arrangement can live. Children will continue adding to and changing the arrangement over the course of the week. Take photographs throughout the process to document how the arrangement changes with each new collaboration.", "When the collaborative arrangement is finished, the nature materials can be put in a sensory table for further exploration, or brought outside to the play yard.", "Invite children to make nature arrangements outside. They could find sticks to place as a “frame” around their arrangement."]], ["Standards", ["SEL7: The child will demonstrate the ability to communicate with others in a variety of ways.", "APL4: The child will demonstrate creativity in thinking and use of materials.", "L.PK.5c. Apply words learned in classroom activities to real-life examples (e.g., name places in school that are fun, quiet, or noisy).", "PK.CC.C.5. Use comparative language, such as more/less than, equal to, to compare and describe collections of objects."]]]}, {"title": "Building Autumn Trees 2", "center": "Blocks", "lead": "This week you can continue building autumn trees with blocks, and you will find new materials to include in your structures, too.", "img": "assets/focus-3s/unit-2/week-1/centers/building-autumn-trees.png", "alt": "Illustration of a child adding autumn leaves to a tree constructed from wooden blocks.", "source": "https://drive.google.com/file/d/1-Lpb1glogfAFzgKNLbZX1Kkq3OflK90m/view", "notes": [["Continued from Week 1", ["Use teacher-held printed photographs of the children’s actual autumn trees. Invite their creators to describe the constructions. The on-screen image is an existing companion illustration, not a photograph of this class’s work. No child-work photographs are uploaded or stored here."]], ["Vocabulary", ["autumn: the season between summer and winter, also called “fall,” when the air gets cooler and leaves start to fall", "branch: a woody part of the tree that grows out of the trunk"]], ["Additional Materials", ["loose parts/“beautiful stuff” (e.g. paper towel rolls, recyclables)", "natural loose parts (e.g. acorns, rocks)", "real leaves, branches and sticks", "tape (for taping leaves and natural materials to blocks)", "printed photographs of children’s autumn trees"]], ["Preparation", ["Sort the beautiful stuff and natural materials into baskets, bowls, or trays and set them out in the Block Center."]], ["Intro to Centers", ["Have you been to the Block Center yet? Many of you have been busy building autumn trees with unit blocks and colored blocks. Autumn is the season we are in now - between summer and winter. Let’s look at some of the trees you have built.", "Show printed photographs of some of the children’s autumn trees. Invite the creators to share about their construction.", "This week you can continue building autumn trees with blocks, and you will find new materials to include in your structures, too: recycled materials [hold up examples], leaves, and branches, the part of the tree that grows out from the trunk, from real trees."]], ["Extension", ["Invite children to label their trees with color names, parts of trees, or other words they want to include."]], ["Standards", ["RI.PreK.7 With prompting and support, describe important details from an illustration or photograph.", "PreK-PS1-4(MA) Recognize through investigation that physical objects and materials can change under different circumstances.", "PreK.SEL7 The child will demonstrate the ability to communicate with others in a variety of ways.", "PreK.APL4 The child will demonstrate creativity in thinking and use of materials.", "PreK.MD.A.1 Recognize the attributes of length, area, weight, and capacity of everyday objects using appropriate vocabulary (e.g., long, short, tall, heavy, light, big, small, wide, narrow)."]]]}];
  const tuesdayPlan=[{"center": "Dramatic Play", "activity": "Making Soup", "img": "assets/focus-3s/unit-2/week-1/centers/cooking-soup.jpg", "alt": "Existing companion illustration of children making soup together, with vegetables, a pot, a spoon and salt and pepper containers.", "source": "https://drive.google.com/file/d/16cqPaCv0iT5vULAwvqS5S1HSpLFTFwim/view", "links": [["Spice labels", "https://drive.google.com/file/d/15T8XZlNzBnzVkHwAmetHptVD7sjyAsJN/view"]], "notes": [["Continued from Week 1", ["This Week 2 introduction continues pretend cooking in Dramatic Play, adding recipes, cookbooks and pretend spices. Use the physical props listed below; the companion illustration is not a photograph of this class."]], ["Vocabulary", ["chop: cut into small pieces", "ingredients: things that are mixed together to make a dish", "peel: to take off the skin from a fruit or vegetable", "prepare: to make something", "recipe: a list of ingredients and directions for making food", "stir: to mix by moving a spoon/ladle in a circle"]], ["Additional Materials", ["Soup Day, Melissa Iwai. Flag the recipe at the end of the book.", "recipes or cookbooks. Flag pages with soup recipes.", "pretend spices or empty spice containers or something to represent spice containers", "spice labels (to add to empty containers or taped to blocks)"]], ["Preparation", ["Bring the following to the Intro to Centers: Soup Day, a pot, a ladle, a few spices."]], ["Intro to Centers", ["Did you visit Dramatic Play last week? Remember all of the different kinds of soup we made?", "Invite a few children to share their experiences in the Center so far.", "This week, we will continue to be chefs in the kitchen making different kinds of soup. This week, I added a few soup recipes and cookbooks for you to reference. Remember that a recipe includes ingredients and directions to follow to cook something. There is a recipe at the end of Soup Day!", "Show the recipe in Soup Day. Point to the ingredients list and the directions. Read aloud.", "You and a friend might work together to make Vegetable Soup when you visit Dramatic Play.", "I also added a few new spices to Dramatic Play such as salt and pepper. These spices help to change the flavor of food. You might want to use these spices in your soup, as well. You don’t need a lot, just a little bit to adjust the taste of your soup.", "Show the spices. Demonstrate adding some salt and pepper to a pot."]], ["Standards", ["SEL7: The child will demonstrate the ability to communicate with others in a variety of ways.", "SEL8: The child will engage socially, and build relationships with other children and with adults.", "APL5: The child will cooperate with others in play and learning.", "SL.PK.1. Participate in collaborative conversations with diverse partners during daily routines and play."]]], "title": "Vocabulary", "lead": "Recipe: a list of ingredients and directions for making food.", "words": ["chop: cut into small pieces", "ingredients: things that are mixed together to make a dish", "peel: to take off the skin from a fruit or vegetable", "prepare: to make something", "recipe: a list of ingredients and directions for making food", "stir: to mix by moving a spoon/ladle in a circle"]}, {"center": "Dramatic Play", "activity": "Making Soup", "img": "assets/focus-3s/unit-2/week-1/soup-day/pages-29-30.jpg", "alt": "Original Soup Day recipe spread: Snowy Day Vegetable Soup ingredients and numbered cooking directions.", "source": "https://drive.google.com/file/d/16cqPaCv0iT5vULAwvqS5S1HSpLFTFwim/view", "links": [["Spice labels", "https://drive.google.com/file/d/15T8XZlNzBnzVkHwAmetHptVD7sjyAsJN/view"]], "notes": [["Continued from Week 1", ["This Week 2 introduction continues pretend cooking in Dramatic Play, adding recipes, cookbooks and pretend spices. Use the physical props listed below; the companion illustration is not a photograph of this class."]], ["Vocabulary", ["chop: cut into small pieces", "ingredients: things that are mixed together to make a dish", "peel: to take off the skin from a fruit or vegetable", "prepare: to make something", "recipe: a list of ingredients and directions for making food", "stir: to mix by moving a spoon/ladle in a circle"]], ["Additional Materials", ["Soup Day, Melissa Iwai. Flag the recipe at the end of the book.", "recipes or cookbooks. Flag pages with soup recipes.", "pretend spices or empty spice containers or something to represent spice containers", "spice labels (to add to empty containers or taped to blocks)"]], ["Preparation", ["Bring the following to the Intro to Centers: Soup Day, a pot, a ladle, a few spices."]], ["Intro to Centers", ["Did you visit Dramatic Play last week? Remember all of the different kinds of soup we made?", "Invite a few children to share their experiences in the Center so far.", "This week, we will continue to be chefs in the kitchen making different kinds of soup. This week, I added a few soup recipes and cookbooks for you to reference. Remember that a recipe includes ingredients and directions to follow to cook something. There is a recipe at the end of Soup Day!", "Show the recipe in Soup Day. Point to the ingredients list and the directions. Read aloud.", "You and a friend might work together to make Vegetable Soup when you visit Dramatic Play.", "I also added a few new spices to Dramatic Play such as salt and pepper. These spices help to change the flavor of food. You might want to use these spices in your soup, as well. You don’t need a lot, just a little bit to adjust the taste of your soup.", "Show the spices. Demonstrate adding some salt and pepper to a pot."]], ["Standards", ["SEL7: The child will demonstrate the ability to communicate with others in a variety of ways.", "SEL8: The child will engage socially, and build relationships with other children and with adults.", "APL5: The child will cooperate with others in play and learning.", "SL.PK.1. Participate in collaborative conversations with diverse partners during daily routines and play."]]], "title": "Connect", "lead": "Remember that a recipe includes ingredients and directions to follow to cook something. There is a recipe at the end of Soup Day!", "enlarge": true}, {"center": "Dramatic Play", "activity": "Making Soup", "img": "assets/focus-3s/unit-2/week-1/centers/cooking-soup.jpg", "alt": "Existing companion illustration of children making soup together, with vegetables, a pot, a spoon and salt and pepper containers.", "source": "https://drive.google.com/file/d/16cqPaCv0iT5vULAwvqS5S1HSpLFTFwim/view", "links": [["Spice labels", "https://drive.google.com/file/d/15T8XZlNzBnzVkHwAmetHptVD7sjyAsJN/view"]], "notes": [["Continued from Week 1", ["This Week 2 introduction continues pretend cooking in Dramatic Play, adding recipes, cookbooks and pretend spices. Use the physical props listed below; the companion illustration is not a photograph of this class."]], ["Vocabulary", ["chop: cut into small pieces", "ingredients: things that are mixed together to make a dish", "peel: to take off the skin from a fruit or vegetable", "prepare: to make something", "recipe: a list of ingredients and directions for making food", "stir: to mix by moving a spoon/ladle in a circle"]], ["Additional Materials", ["Soup Day, Melissa Iwai. Flag the recipe at the end of the book.", "recipes or cookbooks. Flag pages with soup recipes.", "pretend spices or empty spice containers or something to represent spice containers", "spice labels (to add to empty containers or taped to blocks)"]], ["Preparation", ["Bring the following to the Intro to Centers: Soup Day, a pot, a ladle, a few spices."]], ["Intro to Centers", ["Did you visit Dramatic Play last week? Remember all of the different kinds of soup we made?", "Invite a few children to share their experiences in the Center so far.", "This week, we will continue to be chefs in the kitchen making different kinds of soup. This week, I added a few soup recipes and cookbooks for you to reference. Remember that a recipe includes ingredients and directions to follow to cook something. There is a recipe at the end of Soup Day!", "Show the recipe in Soup Day. Point to the ingredients list and the directions. Read aloud.", "You and a friend might work together to make Vegetable Soup when you visit Dramatic Play.", "I also added a few new spices to Dramatic Play such as salt and pepper. These spices help to change the flavor of food. You might want to use these spices in your soup, as well. You don’t need a lot, just a little bit to adjust the taste of your soup.", "Show the spices. Demonstrate adding some salt and pepper to a pot."]], ["Standards", ["SEL7: The child will demonstrate the ability to communicate with others in a variety of ways.", "SEL8: The child will engage socially, and build relationships with other children and with adults.", "APL5: The child will cooperate with others in play and learning.", "SL.PK.1. Participate in collaborative conversations with diverse partners during daily routines and play."]]], "title": "Model adding spices", "lead": "Show the spices. Demonstrate adding some salt and pepper to a pot.", "steps": [["Spices", "These spices help to change the flavor of food."], ["Just a little", "You don’t need a lot, just a little bit to adjust the taste of your soup."]]}, {"center": "Dramatic Play", "activity": "Making Soup", "img": "assets/focus-3s/unit-2/week-1/centers/cooking-soup.jpg", "alt": "Existing companion illustration of children making soup together, with vegetables, a pot, a spoon and salt and pepper containers.", "source": "https://drive.google.com/file/d/16cqPaCv0iT5vULAwvqS5S1HSpLFTFwim/view", "links": [["Spice labels", "https://drive.google.com/file/d/15T8XZlNzBnzVkHwAmetHptVD7sjyAsJN/view"]], "notes": [["Continued from Week 1", ["This Week 2 introduction continues pretend cooking in Dramatic Play, adding recipes, cookbooks and pretend spices. Use the physical props listed below; the companion illustration is not a photograph of this class."]], ["Vocabulary", ["chop: cut into small pieces", "ingredients: things that are mixed together to make a dish", "peel: to take off the skin from a fruit or vegetable", "prepare: to make something", "recipe: a list of ingredients and directions for making food", "stir: to mix by moving a spoon/ladle in a circle"]], ["Additional Materials", ["Soup Day, Melissa Iwai. Flag the recipe at the end of the book.", "recipes or cookbooks. Flag pages with soup recipes.", "pretend spices or empty spice containers or something to represent spice containers", "spice labels (to add to empty containers or taped to blocks)"]], ["Preparation", ["Bring the following to the Intro to Centers: Soup Day, a pot, a ladle, a few spices."]], ["Intro to Centers", ["Did you visit Dramatic Play last week? Remember all of the different kinds of soup we made?", "Invite a few children to share their experiences in the Center so far.", "This week, we will continue to be chefs in the kitchen making different kinds of soup. This week, I added a few soup recipes and cookbooks for you to reference. Remember that a recipe includes ingredients and directions to follow to cook something. There is a recipe at the end of Soup Day!", "Show the recipe in Soup Day. Point to the ingredients list and the directions. Read aloud.", "You and a friend might work together to make Vegetable Soup when you visit Dramatic Play.", "I also added a few new spices to Dramatic Play such as salt and pepper. These spices help to change the flavor of food. You might want to use these spices in your soup, as well. You don’t need a lot, just a little bit to adjust the taste of your soup.", "Show the spices. Demonstrate adding some salt and pepper to a pot."]], ["Standards", ["SEL7: The child will demonstrate the ability to communicate with others in a variety of ways.", "SEL8: The child will engage socially, and build relationships with other children and with adults.", "APL5: The child will cooperate with others in play and learning.", "SL.PK.1. Participate in collaborative conversations with diverse partners during daily routines and play."]]], "title": "Play together", "lead": "You and a friend might work together to make Vegetable Soup when you visit Dramatic Play."}, {"title": "Storytelling with Props", "activity": "Strictly No Elephants", "center": "Library and Listening", "lead": "In Library and Listening this week, you can retell this story, or tell the story again.", "img": "assets/focus-3s/unit-2/week-2/strictly-no-elephants/slide-02.jpg", "alt": "Original beginning of Strictly No Elephants showing the boy and his tiny pet elephant.", "enlarge": true, "source": "https://drive.google.com/file/d/1Ic7k0tA1EY1JlgT6kwnp1VYmHodddZBF/view", "links": [["Storytelling visual support", "https://drive.google.com/file/d/1GRcYmiajzuhTQgJczN5y6xqiIpZyESaY/view"]], "notes": [["Purpose", ["Children use book character puppets and props to retell Strictly No Elephants."]], ["Big Ideas", ["We can all communicate about colors.", "There is an infinite variety of colors."]], ["Guiding Questions", ["What colors do we notice all around us?", "How can we explore and communicate ideas and feelings through colors?", "How do colors provide information?"]], ["Family Engagement", ["Continue to invite families and caregivers to share their children’s favorite books/stories to retell in the Library and Listening Center. If families share titles of stories, share the story electronically or find the title at the library."]], ["Vocabulary", ["character: a person or animal in a story, play, or movie", "retell: to tell a story again"]], ["Materials and Preparation", ["Strictly No Elephants, Lisa Mantchev", "Strictly No Elephants character puppets (included with Read Aloud plans)", "small basket or container to hold character puppets", "large fabric swatches", "additional props such as stuffed animals, animal figurines, an umbrella", "white paper", "writing and drawing tools", "glue sticks or tape, to make additional puppets/props", "popsicle sticks, to make additional puppets/props", "scissors, to make additional puppets/props", "Bring the following to the Intro to Centers: Strictly No Elephants, character puppets, 1 fabric swatch, additional props"]], ["Intro to Centers", ["We enjoyed reading Strictly No Elephants. In Library and Listening this week, you can retell this story, or tell the story again.", "Show Strictly No Elephants.", "To help you retell the story, the character puppets will be in Library and Listening.", "Show the character puppets. Open to the beginning of Strictly No Elephants and invite children to describe the scene and narrate what is happening. Demonstrate using the puppet(s) to act out the scene, using vocabulary and dialogue.", "I also added some more items to the Center. You will find fabric swatches and a few additional props. You might decide to also use these items to help you retell the story.", "Show fabric and props."]], ["During Centers", ["Children retell the story using the character puppets and/or the props. Support children to negotiate choosing puppets/props. A child without a puppet might be the narrator who turns the pages of the book to help the actors retell the story.", "Children might want to create additional props such as the “Strictly No Elephants sign” or pet puppets.", "Affirm children’s impulses to change the story in original ways."]], ["Differentiation Ideas", ["Turn the pages of the book to help children remember one story event at a time; talk through what’s happening in the illustration and/or reread the text; make suggestions about what a character can say.", "Use story sequencing visuals from the visual comprehension resource included in the differentiated access for each read aloud.", "Invite children to draw a character or an event in a story.", "Invite children to retell an alternate ending or add characters."]], ["Facilitation", ["What happens in this book?", "What is happening here with the characters, the people or animals in the story?", "How do you think the character feels during this part?", "Has something like this ever happened to you? Tell us about what happened.", "How might you tell a different ending to the story?"]], ["Extensions", ["Invite children to retell additional favorite books from home or teachers’ favorite books."]], ["Standards", ["SEL5. The child will display empathetic characteristics.", "APL5. The child will cooperate with others in play and learning.", "APL8. The child will be able to retain and recall information.", "RL.PK.2. With prompting and support, retell a sequence of events from a story read aloud."]]]}];
  const wednesdayPlan=[{"title": "Collecting Leaves", "center": "Math", "lead": "Today in the Math Center we are going to play a game with colorful leaves, and a five frame. A five frame is a strip with 5 boxes in a row to help you count.", "img": "assets/focus-3s/unit-2/week-1/centers/autumn-leaves.png", "alt": "Companion illustration of autumn leaves sorted on a table; it does not show a five frame or this class’s own work.", "source": "https://drive.google.com/file/d/1bqGqdYc1DBvsRSh59sHmLEVQoB2Es72n/view", "notes": [["Source and Teaching Materials", ["The weekly plan calls this activity Leaf Collections; the source lesson is titled Math: Collecting Leaves. The on-screen companion illustration shows leaves sorted on a table; it is not a five-frame demonstration or a photograph of this class’s work. Use the physical number cards or die, five frame, leaves, and book listed below for the demonstration."]], ["Purpose", ["Children demonstrate one to one correspondence by adding leaves to a five frame ."]], ["Big Ideas", ["Color is a property of many natural and human-made things.", "Colors can be mixed to make new colors."]], ["Objective", ["I am learning to count objects to 5. (Learning Trajectories, p. 1-2)"]], ["Guiding Questions", ["What colors do we notice all around us?", "How do colors provide information?"]], ["Family Engagement", ["Encourage families and caregivers to collect leaves with children. Encourage them to look at the leaves, notice the colors and count the number of leaves they find."]], ["Vocabulary", ["less: a smaller amount than something else", "more: a bigger amount than something else", "equal: the same amount as something else"]], ["Materials and Preparation", ["Goodbye Summer, Hello Autumn, Kenard Pak", "Flag a page with autumn leaves in the illustration.", "number dot cards 0-5 or dice 0-5 enough for each child at the center (see Week 1)", "blank 5 frame, one for each child", "Cut out.", "leaf template", "Cut out the leaves. Make enough so that each child could have up to 5.", "Building Blocks Teacher’s Guide pg. 104 week 7"]], ["Intro to Centers", ["Today in the Math Center we are going to play a game with colorful leaves, and a five frame. A five frame is a strip with 5 boxes in a row to help you count.", "Hold up the five frame.", "These leaves are similar to the leaves in Goodbye Summer, Hello Autumn. The leaves in the story are green, red, yellow, and brown. Just like the leaves we are going to use today to play a game in the math center.", "First we are going to pull a Number Card from the pile (or roll a die). What number is this? How did you know this was a ____? Let’s count to make sure it is a _____?", "Count out loud with children.", "Now we are going to add that many leaves/leaf to our five frame. Let’s count as we add them to five frame.", "What if we want one more leaf on the tree? More means a bigger amount than something else. What can we do?", "Harvest children’s ideas.", "What If we want one less leaf on the tree? Less means a smaller amount of something. What can we do?", "Harvest children’s ideas.", "What if I want the same amount as my friend _____? The same amount is equal. They have 1 and I want 1. What can I do?", "Harvest children’s ideas.", "We will play this game at the Math Center."]], ["During Centers", ["Encourage children to pull a card or roll a die. Have them count to see how many they will add to their five frame. Then count the leaves to see if it is the same as the card they pulled."]], ["Differentiation Ideas", ["Count using lower numbers (0-5).", "Use larger sized objects or felt for leaves.", "Place velcro on the leaves and where they go (on 5-frame and/or tree) so that they stay in place when children are counting.", "Use 5-frame cards with or without numerals (0-5).", "For a more tactile 5-frame, use wiki sticks or craft sticks to demarcate the lines on the 5-frame or cut an egg cart down to 5 spaces.", "Use the tree templates pre-marked with spaces for leaves on the tree (located in the adapted resource folder).", "Say the number without showing the card.", "As an extension, count up to higher numbers (5-10)."]], ["Facilitation", ["How many leaves do you have on your five frame? How do you know?", "What if you added one more, how many do you have on your five frame now?", "Do you have more or less than ______? How do you know?"]], ["Standards", ["PreK.SEL7 The child will demonstrate the ability to communicate with others in a variety of ways.", "PreK.APL4 The child will demonstrate creativity in thinking and use of materials.", "PK.CC.A Know number names and the counting sequence.", "1. Listen to and say the names of numbers in meaningful contexts"]]], "enlarge": true, "links": [["Five- and ten-frame templates", "https://drive.google.com/file/d/1PqVMmC4wmQuMNsglFOhiPf9NPtriCswS/view"], ["Leaf template", "https://drive.google.com/file/d/1Y6GuMrAJLskrQnI4gX0wnJe5TByqKhJ7/view"]], "enlargeLabel": "Enlarge image", "activity": "Leaf Collections"}, {"title": "Multilingual Color Poem or Book", "center": "Writing and Drawing", "lead": "Today we will write our own book [or poem] using the color words we know in our languages.", "img": "assets/focus-3s/unit-2/week-2/centers/favorite-objects-visual-menu.png", "alt": "Original Favorite Objects visual support with a menu of favorite objects and color choices.", "source": "https://drive.google.com/file/d/1MHDgTJvV3OSf9b8Z87OHTTaV_dMUIeTF/view", "notes": [["Source Examples and Classroom Languages", ["The names, objects, and languages in the source poem below are fictional teaching examples, not information about children in this class. Use the children’s actual contributions and family-supported color words; do not infer the languages spoken in this classroom from the examples.", "Use the source’s monolingual alternative when applicable: name the language spoken and some other languages spoken by others in the school community. The source’s statements about a multilingual classroom apply only when that describes the class.", "The on-screen image is the original Favorite Objects visual support, provided to help children choose an object and a color. It is not a finished class poem or book. Use a physical copy of the chosen book, prepared color cards, and the children’s own drawings for the activity."]], ["Purpose", ["Children write a poem or book together using color words in the languages they speak."]], ["Big Ideas", ["Color is a property of many natural and human-made things.", "We can all communicate about colors."]], ["Guiding Question", ["What colors do we notice all around us?", "How can we explore and communicate ideas and feelings through colors?"]], ["Family Engagement", ["Invite families to share the names of colors in their languages. Create cards or a list of the color names for each language spoken by children and teachers in the class."]], ["Vocabulary", ["favorite: the one you like the most", "multilingual: knowing more than one or many languages", "poem: a piece of writing that can rhyme and usually expresses imagination and emotion", "Color words in languages spoken by children in the class (e.g. Spanish: azul: blue amarillo: yellow rojo:red)"]], ["Materials and Preparation", ["Green Is a Chile Pepper or Red is a Dragon, Roseanne Thong", "chart paper", "markers", "poem example", "If creating a poem, write the poem on the chart paper.", "Green Is a Chile Pepper visual glossary, from Week 2, Read Aloud", "Favorite Objects visual (optional)", "Gather the names of colors in the languages spoken in the class. Ask families to support or use online resources such as Google Translate.", "Decide if you want to create a class poem or a class book. If a poem, see the example below. If creating a book, children can create individual or shared pages to contribute."]], ["Poem Example — Fictional Source Examples", ["Our Favorite Colors", "[use this pattern to create a class poem using the children’s names and favorite items]", "We love colors in all our languages!", "Maya loves blue flowers - azul (Spanish)", "María loves yellow butterflies - amarelo (Portuguese)", "Iman loves green trains - أخضر (pronounced akhdar - Arabic)", "…[continue for all children in the class]", "We love colors in all our languages!"]], ["Intro to Centers", ["In Green is a Chile Pepper, all of the color words are written in two languages, English and Spanish.", "Look through the book and read some of the words together.", "In our classroom, we speak many different languages.", "If the classroom is monolingual, name the language spoken and some other languages spoken by others in the school community.", "What language do you speak with your family?", "Invite children to share and support them if they are unsure. Teachers can also share the languages they speak.", "Having more than one language in our classroom is amazing, our community is multilingual.", "Today we will write our own book [or poem] using the color words we know in our languages. You can add the name of your favorite color in your language or a language you are excited about. We can also draw pictures of things that are that color to illustrate our poem."]], ["During Centers", ["Invite children to look at the multilingual color cards and notice the different ways to say the names of the colors. Read some of the color names and track print while reading.", "Invite children to add their own line to the poem or page to the book, by choosing a language and a favorite color/object to include.", "Invite children to create illustrations for the poem or book page. If writing a poem, the illustrations can be made on small pieces of paper, and cut/glued around the edges of the poem to decorate.", "Read the poem/book back to the children as it is created."]], ["Differentiation Ideas", ["Add in more words in children’s home languages, if known (i.e. not just the color word but also objects or feelings).", "Use the favorite objects communication support (see below) to support children with choosing an object and its color.", "Invite children to select their favorite color from a set of color cards or from objects around the room, providing them the word in English or another language."]], ["Facilitation", ["What is your favorite color? Why do you like it the most?", "How do you say [color name] in your language?", "What is something you love that is (blue, red…)? Why do you love it?", "How will you draw your [red balloon…] to illustrate our poem/book?", "How is the way you say yellow in [Spanish] different from [Arabic]?"]], ["Extensions", ["Encourage children to join you in reading the poem/book or tracking print while you read aloud. Rather than expecting them to read all the words, focus their attention on their own and their friends’ names, which they might recognize in print.", "Make printed copies of the finished poem or book to send home so that children can share and read with their families.", "Read the poem or book in the end-of-unit celebration."]], ["Standards", ["W.PreK.1 Dictate words to express a preference or opinion about a topic (e.g., “I would like to go to the fire station to see the truck and meet the firemen.”).", "W.PreK.2 Use a combination of dictating and drawing to supply information about a topic.", "RL.PreK.9 With prompting and support, make connections between a story or poem and their own experiences.", "PreK.SEL7 The child will demonstrate the ability to communicate with others in a variety of ways."]]], "enlarge": true, "links": [["Favorite Objects visual support", "https://drive.google.com/file/d/18nr-9epY24TXFg1WR-GDSyok2jGp-jgD/view"]], "enlargeLabel": "Enlarge image", "activity": "Multilingual Color Poem"}];
  const thursdayPlan=[{"title": "Class Soup", "center": "Science and Engineering", "activity": "Cooking Real Soup", "lead": "Today we will cook a real soup together! Let’s look at the recipe. This is the list of food that we will need and also the directions.", "img": "assets/focus-3s/unit-2/week-1/friday/follow-a-recipe.png", "alt": "Companion illustration of an adult and child looking at a picture recipe with colorful vegetables and cooking steps; this is not the class’s selected recipe.", "source": "https://drive.google.com/file/d/1GtykjF_jo1HNCA69lk5gJjCbpsczXL-n/view", "notes": [["Source and Teaching Materials", ["This is the real-food Class Soup activity, distinct from the pretend soup in Dramatic Play. Use your selected recipe and the physical materials below. The on-screen companion illustration shows an adult and child looking at a picture recipe; it is not the class’s selected recipe, a required ingredient list, or a photograph of this class. The source’s Bryce, Camilla, and Yoshi example illustrates taking turns and does not identify children in this class."]], ["Purpose", ["Children cook real soup together."]], ["Big Ideas", ["Color is a property of many natural and human-made things. There is an infinite variety of colors."]], ["Guiding Question", ["What colors do we notice all around us? How do colors provide information?"]], ["Family Engagement", ["Invite families and caregivers to share their favorite soup. This could be a recipe, or photograph, an herb packet, or even donated empty food containers (e.g., an empty box of noodles). If interested, invite family members to share their expertise by coming in to talk about the food or demonstrating how to cook the food. Invite caregivers to come into cook soup together with the children."]], ["Vocabulary", ["gather: to collect things", "ingredients: things that are mixed together to make a dish", "mix: put different things together", "prepare: to make something", "recipe: a list of ingredients and directions for making food", "stir: to mix by moving a spoon/ladle in a circle"]], ["Materials", ["simple recipe Select a soup recipe that children can easily follow. There is an example in the back of Soup Day or invite families to share a favorite recipe.", "chart paper and markers Transfer the recipe onto chart paper. Where possible make the recipe visual (e.g., next to the “6 cups of broth”, draw out 6 cups).", "ingredients to make the soup To make the cooking process easier, prepare some of the ingredients ahead of time. And leave some of the preparation for the children (e.g, children can help wash and cut vegetables)", "cooking implements such as a large pot, colanders, child-safe cutting tools, ladles", "As an alternative to soup, the class may prepare a fruit or vegetable salad.", "Note: be aware of any food allergies/preferences."]], ["Intro to Centers", ["In the story Green is a Chile Pepper/Red is a Dragon we noticed the many colors of different foods. What foods are special to your family?", "Invite 1-2 responses.", "In Soup Day, the child and mom worked together to cook soup. And you are making soup in Dramatic Play! A soup is made by cooking ingredients slowly in a big pot. In Soup Day, they used ingredients such as carrots, celery, and mushrooms. So many different colors!", "Today we will cook a real soup together! Let’s look at the recipe. This is the list of food that we will need and also the directions.", "Show recipe on chart paper. Point to the sections of the recipe while talking through it.", "I already gathered the ingredients, or the foods that we will need to make the soup. Let’s look at the ingredient list: _____ [list ingredients]. First we will wash the ingredients and chop them into small pieces. Then we will stir them all together in our pot and add seasonings, like salt, pepper, and herbs, for extra flavor. We will make everything very hot so that it cooks all the ingredients. How might our soup change after we add heat to it?", "Harvest responses from children.", "When we’re finished, we can taste the soup we cooked together today during lunch."]], ["During Centers", ["Children first wash their hands and cook soup together. As small groups join the Science and Engineering Center, share what step of the recipe is being followed. Use ordinal language (first, second, third) while following the recipe. Invite children to take turns completing steps of the recipe (e.g., First Bryce will pour in the milk; second, Camilla will add the flour; third Yoshi will stir the ingredients with a spoon.).", "Encourage children to notice the characteristics of the ingredients, such as the color, texture, smell or amount before cooking. Then ask how they think the ingredients might change when we add heat to them", "Sample the warm finished soup together during snack or lunch. Ask children about how the color, texture, and smell of the ingredients changed. Consider making another batch for your Color Party at the end of the unit."]], ["Differentiation Ideas", ["Use the visual soup recipe connected to Soup Day (see Dramatic Play, U2 W1 ) to support children with making a soup.", "Use the cooking topic board (see Dramatic Play, U1 W1) to support children with communication as they prepare a soup with real ingredients.", "Break down the experience over several days, one day each for: exploring the vegetables textures and names, washing the vegetables, cutting the vegetables/making observations about the insides, mixing the vegetables and cooking the soup.", "Use the steps that are appropriate for your classroom.", "Partially cook vegetables (e.g., in a microwave) to make them easier to cut.", "Ensure children know the difference between pretend and real ingredients. Practice with the pretend ingredients before using the real ingredients."]], ["Facilitation", ["How are our ingredients similar to or different from the ones in the book, _____(Soup Day or Green is a Chile Pepper or Red is a Dragon)?", "Which step in the recipe comes first/next? How do you know?", "What foods are special to you and your family?", "Have you eaten soup with your family before? What kind was it?", "What do we need to do first (second, third) to prepare our soup?", "What colors do you see in this soup?", "Why do you like this soup?", "How does the soup change when we add heat to it?"]], ["Standards", ["PreK-LS1-3(MA). Use their five senses in their exploration and play to gather information.", "PreK-PS1-4 (MA) Recognize through investigation that physical objects and materials can change under different circumstances.", "Science and Engineering Practice 3: Planning and Carrying Out Investigations", "SL.PK.1b. Continue a conversation through multiple exchanges."]]], "links": [["Original Class Soup center language supports", "https://drive.google.com/file/d/1aZOmCa-sdQvjF8u5wuWLGBFNU9xIjPl4/view"]], "enlarge": true, "enlargeLabel": "Enlarge image"}];
  const friday=day===4;
  // Each choice owns only its original introduction, never the day's other center.
  const choices=[
    {id:'nature-arrangements',title:'Nature Arrangements',original:[mondayPlan[0]],reminder:mondayPlan[0].lead},
    {id:'building-autumn-trees',title:'Building Autumn Trees',original:[mondayPlan[1]],reminder:mondayPlan[1].lead},
    {id:'cooking-soup',title:'Cooking Soup',original:tuesdayPlan.slice(0,4),reminder:'Continue pretend cooking together. Use the soup recipes, cookbooks and pretend spices in Dramatic Play.'},
    {id:'storytelling-props',title:'Storytelling with Props',original:[tuesdayPlan[4]],reminder:tuesdayPlan[4].lead},
    {id:'leaf-collections',title:'Leaf Collections',original:[wednesdayPlan[0]],reminder:'Revisit the colorful-leaf counting game with a five frame.'},
    {id:'multilingual-color-poem',title:'Multilingual Color Poem',original:[wednesdayPlan[1]],reminder:'Revisit your color book or poem using color words in your classroom languages.'},
    {id:'class-soup',title:'Class Soup',original:thursdayPlan,reminder:'Revisit making real soup together with your class recipe. Notice how the ingredients change with heat.'}
  ];
  let selected=null,reviewing=false;
  let plan=friday?[]:day===3?thursdayPlan:day===2?wednesdayPlan:day===1?tuesdayPlan:mondayPlan;
  window.EEACentersChoices=friday?choices:[];
  const $=id=>document.getElementById(id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let index=0;
  const state=()=>({step:index,index,total:plan.length,atStart:index===0&&(!friday||!reviewing),atEnd:!plan.length||index===plan.length-1,...(friday?{center:selected,review:reviewing}:{})});
  function restore(step,center=null,review=false){
    if(friday){
      const choice=choices.find(c=>c.id===center);selected=choice?.id||null;reviewing=!!choice&&(review===true||review==='1');
      plan=!choice?[]:reviewing?choice.original:[{...choice.original[0],title:choice.title,lead:choice.reminder,words:null,steps:null}];
      window.EEACentersPlan=plan;
    }
    index=Math.max(0,Math.min(plan.length-1,Number.isInteger(Number(step))?Number(step):0));render();
  }
  function choiceParams(url){
    if(friday&&selected)url.searchParams.set('center',selected);else url.searchParams.delete('center');
    if(friday&&reviewing)url.searchParams.set('review','1');else url.searchParams.delete('review');
  }
  window.EEASectionState=state;window.EEACentersRestore=restore;window.EEACentersPlan=plan;
  function route(step,replace=false,center=selected,review=reviewing){
    if(embedded&&typeof parent.EEACentersNavigate==='function'){parent.EEACentersNavigate(step,replace,center,review);return;}
    restore(step,center,review);const url=new URL(location.href);url.searchParams.set('day',days[day]);url.searchParams.set('week','10');url.searchParams.set('section','2');url.searchParams.set('step',String(index));url.searchParams.delete('stop');url.searchParams.delete('book');choiceParams(url);
    if(url.href!==location.href)history[replace?'replaceState':'pushState'](null,'',url.href);
  }
  function render(){const restoreReviewFocus=['review-original','return-choice'].includes(document.activeElement?.id);document.querySelector('.center-tools .review-control')?.remove();const dialog=$('image-dialog');if(dialog?.open)dialog.close();const s=plan[index];if(friday){$('center-choice').value=selected||'';if(!s){$('sub').textContent='Friday · Revisit Center of Choice';$('lesson').innerHTML='<div class="center-empty"><div class="kicker">REVISIT CENTER OF CHOICE</div><h2>Which center shall we revisit?</h2><p class="lead">Choose a center from this week. You can review its original introduction if you wish.</p></div>';$('count').textContent='Choose one center';$('prev').textContent='← Read Aloud';$('done').textContent='Finish Centers →';window.dispatchEvent(new CustomEvent('eea-section-state',{detail:state()}));return;}}$('sub').textContent=days[day]+' · '+s.center+(friday?' · '+(reviewing?'Original introduction':'Revisit Center of Choice'):(s.activity?' · '+s.activity:' · Continued from Week 1'));
    $('lesson').innerHTML=`<article class="community-card"><figure class="community-visual"><img class="lesson-img" src="${s.img}" alt="${escape(s.alt)}">${s.enlarge?`<button type="button" class="enlarge-image">${escape(s.enlargeLabel||'Enlarge pages')}</button>`:''}</figure><div class="community-copy ${s.words||s.steps?'with-steps':''}"><div class="kicker">${escape(s.center.toUpperCase())} · WORLD OF COLOR</div><h2>${escape(s.title)}</h2><div class="lead">${escape(s.lead)}</div>${s.words?`<ul class="vocabulary-list">${s.words.filter(p=>!p.startsWith('recipe:')).map(p=>`<li>${escape(p)}</li>`).join('')}</ul>`:''}${s.steps?`<ol class="teaching-steps">${s.steps.map(([t,p])=>`<li><b>${escape(t)}</b><p>${escape(p)}</p></li>`).join('')}</ol>`:''}${friday?`<button type="button" class="review-control" id="${reviewing?'return-choice':'review-original'}">${reviewing?'Return to selected center':'Review original introduction'}</button>`:''}<details class="community-notes"><summary>Teacher Notes</summary><div class="community-notes-content">${s.notes.map(([title,paragraphs])=>`<h3>${escape(title)}</h3>${paragraphs.map(p=>`<p>${escape(p)}</p>`).join('')}`).join('')}<h3>Source materials</h3><ul>${(s.links||[]).map(([label,url])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${escape(label)}</a></li>`).join('')}<li><a href="${s.source}" target="_blank" rel="noopener noreferrer">Original Week 2 lesson</a></li><li><a href="https://docs.google.com/document/d/1lYe4_XN0sIUJeeEt2kbxzxtzqkteNSX9woHXpfXlb7Y/edit" target="_blank" rel="noopener noreferrer">Original Week 2 Plan</a></li></ul><p>Focus on Pre-K 3s | Boston Public Schools Early Childhood Department P-2</p></div></details></div></article>`;
    $('count').textContent=(index+1)+' of '+plan.length;$('prev').textContent=index===0?'← Read Aloud':'← Previous';$('done').textContent=index===plan.length-1?'Finish Centers →':day===0?'Next: Building Autumn Trees →':day===2?'Next: Color Poem →':index===3?'Next: Storytelling →':'Next →';
    if(friday){$('prev').textContent=reviewing&&index===0?'← Selected center':index===0?'← Read Aloud':'← Previous';$('count').textContent=reviewing?'Review · '+(index+1)+' of '+plan.length:'Selected center';$('done').textContent=index===plan.length-1?'Finish Centers →':'Next →';const review=$('review-original'),back=$('return-choice');if(review)review.onclick=()=>route(0,false,selected,true);if(back)back.onclick=()=>route(0,false,selected,false);if(review||back){document.querySelector('.center-tools').append(review||back);if(restoreReviewFocus)(review||back).focus();}}
    const enlarge=document.querySelector('.enlarge-image');if(enlarge)enlarge.onclick=()=>{const dialog=$('image-dialog');dialog.setAttribute('aria-label',day>=2?'Enlarged lesson image':'Enlarged book pages');$('enlarged-image').src=s.img;$('enlarged-image').alt=s.alt;enlarge.focus();dialog.showModal();};if(enlarge){const image=document.querySelector('.lesson-img');image.onclick=enlarge.onclick;image.style.cursor='zoom-in';}
    window.dispatchEvent(new CustomEvent('eea-section-state',{detail:state()}));
  }
  if(friday){
    document.body.classList.add('friday-centers');
    const label=document.createElement('label');label.className='center-choice-label';label.htmlFor='center-choice';label.textContent='Choose a center';
    const select=document.createElement('select');select.id='center-choice';select.className='activity-menu';
    select.innerHTML='<option value="">Choose a center…</option>'+choices.map(c=>`<option value="${c.id}">${escape(c.title)}</option>`).join('');
    label.append(select);const tools=document.createElement('div');tools.className='center-tools';tools.append(label);$('sub').after(tools);select.onchange=()=>route(0,false,select.value,false);
  }
  $('close-image').onclick=()=>$('image-dialog').close();
  $('image-dialog').addEventListener('click',event=>{if(event.target!==$('image-dialog'))return;const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.currentTarget.close();});
  $('exit').onclick=overview;
  $('prev').onclick=()=>{if(index>0){route(index-1);return;}if(friday&&reviewing){route(0,false,selected,false);return;}if(embedded&&typeof parent.EEAWeek10PreviousCenters==='function')parent.EEAWeek10PreviousCenters();else destination.location.href='lesson-runner-week10.html?week=10&day='+day+'&section=1';};
  $('done').onclick=()=>{if(index<plan.length-1){route(index+1);return;}if(embedded&&typeof parent.EEAWeek10CompleteCenters==='function')parent.EEAWeek10CompleteCenters();else overview();};
  window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);restore(p.get('step'),p.get('center'),p.get('review'));});
  window.addEventListener('pageshow',()=>{const p=new URLSearchParams(destination.location.search);restore(p.get('step'),p.get('center'),p.get('review'));});
  route(params.get('step')||0,true,params.get('center'),params.get('review'));
})();
